mapper.select:
SELECT v.id, v.title, v.description, v.cover_url AS coverUrl, v.duration, v.view_count AS viewCount, v.like_count AS likeCount, v.favorite_count AS favoriteCount, v.publish_time AS publishTime, v.author_id AS authorId, u.nickname AS authorNickname, v.category_id AS categoryId, c.name AS categoryName FROM video v INNER JOIN sys_user u ON v.author_id = u.id INNER JOIN video_category c ON v.category_id = c.id WHERE v.status = 'PUBLISHED'
AND v.category_id = #{categoryId}
ORDER BY v.publish_time DESC, v.id DESC
